from bs4 import BeautifulSoup
soup = BeautifulSoup('<div><p>1</p><p>2</p></div>', 'html.parser')
for p in soup.find_all('p'):
    if p.string == '1':
        p.replace_with(soup.new_tag('span'))
print(len(soup.find_all('p')))

from bs4 import BeautifulSoup
soup = BeautifulSoup('<p>Hello</p>', 'html.parser')
def custom_formatter(string):
    return string.upper()
print(soup.p.encode(formatter=custom_formatter))

from bs4 import BeautifulSoup
soup = BeautifulSoup('<div><p>A</p><p>B</p></div>', 'html.parser')
for i, p in enumerate(soup.find_all('p')):
    if i == 0:
        p.decompose()
